package dao;import model.*;import java.sql.*;import java.util.*;
public class MembershipCardDAO5 extends DAO5{public MembershipCardDAO5(Connection c){super(c);}public MembershipCard5 getValidCard(String code)throws Exception{List<MembershipCard5>a=query(MembershipCard5.class,"SELECT * FROM tblMembershipCard5 WHERE MaThe=? AND TrangThai='HIEU_LUC' AND ThoiHan>=CURRENT_DATE",code);if(a.isEmpty())throw new IllegalArgumentException("Thẻ không hợp lệ hoặc đã hết hạn");return a.get(0);}public MembershipCard5 forCustomer(int id)throws Exception{List<MembershipCard5>a=query(MembershipCard5.class,"SELECT * FROM tblMembershipCard5 WHERE tblCustomer5id=?",id);return a.isEmpty()?null:a.get(0);}}
